    'admin_leader_operating_system.leader.opportunity_modal_intro' => 'Das Wachstumspotenzial liegt derzeit bei %s. Unten findest du die Änderungen und Maßnahmen, die diesem Partner am ehesten helfen können, schneller voranzukommen und das Ergebnis zu verbessern.',
    'admin_leader_operating_system.leader.opportunity_modal_empty' => 'Derzeit gibt es keine zusätzlichen Signale. Der Fokus sollte aber auf klareren Handlungsaufforderungen, einer besseren Conversion und einem einfacheren Weg zur Registrierung oder zum Kauf bleiben.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.label' => 'Den Anteil der Klicks auf Webshop oder Rabattziele erhöhen',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.text' => 'Der Partner hat insgesamt %s Klicks, aber nur %s%% davon führen zum Forever Webshop oder zu Rabattseiten.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_1' => 'Platziere den Button zum Webshop oder Rabatt weiter oben auf der Seite und wiederhole ihn weiter unten im Profil oder Blogbeitrag.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_2' => 'Füge auf dem wichtigsten Besucherpfad eine klarere Handlungsaufforderung hinzu, damit Besucher zu einem Forever Ziel gelangen und nicht nur zu informativen Inhalten.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_2_source' => 'Teste für die Quelle %s eine klarere Handlungsaufforderung, die Nutzer direkt vom Inhalt zum Forever Webshop oder zum Rabattangebot führt.',
    'admin_leader_operating_system.leader.opportunity_action.more_shop_share.step_3' => 'Prüfen Sie, ob Blog, Verkaufsblöcke und Rabattblöcke den Kaufweg ausreichend sichtbar machen und oft genug zeigen.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.label' => 'Klicks im Webshop in Registrierungen oder Käufe umwandeln',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.text' => 'Der Mitarbeiter hat bereits %s Webshop-Klicks, aber in diesem Zeitraum noch keine Registrierungen.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_1' => 'Prüfe, ob der Klick die richtige Empfehlungs-URL öffnet und ohne Fehler auf der vorgesehenen Seite oder Webshop-Ansicht landet.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_2' => 'Verbessere die Nachricht vor dem Klick: Erkläre, was Besucher erhalten, warum sie jetzt klicken sollten und was nach dem Aufrufen der Forever Seite passiert.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_3' => 'Teste einen einfacheren Weg zur Registrierung oder zum Kauf und entferne verwirrende Schritte nach dem ersten Klick.',
    'admin_leader_operating_system.leader.opportunity_action.unlock_registrations.step_3_country' => 'Wenn der meiste Traffic aus %s kommt, prüfe, ob die Zielseite richtig lokalisiert ist und die passende Marktversion öffnet.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.label' => 'Konversionsrate steigern, während der Besucherverkehr wächst',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.text' => 'Der Traffic wächst um %s%%, aber die Registrierungsrate liegt nur bei %s%%. Zusätzliche Klicks führen also noch nicht zu genügend Ergebnissen.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_1' => 'Behalte die Quelle bei, die das Wachstum antreibt, aber verbessere den Text der Handlungsaufforderung und die einleitende Nachricht, damit sie die Kaufabsicht besser erkennen lassen.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_2' => 'Schaffe vor dem Handlungsaufruf Vertrauen: mit einer Kundenstimme, einem Ergebnis, kurzen häufig gestellten Fragen oder einer klaren Erklärung, was nach dem Klick passiert.',
    'admin_leader_operating_system.leader.opportunity_action.raise_conversion_rate.step_3' => 'Vergleiche die Quellen der Klicks und priorisiere weiterhin nur die Kanäle, die Anmeldungen oder qualifiziertere Interessenten bringen, nicht bloß viele Besuche.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.label' => 'Bestehendes Interesse für einen stärkeren Verkaufsweg nutzen',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.text' => 'Die App erzeugt bereits Signale über WhatsApp (%1$s), Produkte (%2$s) und Registrierungen (%3$s), aber dadurch gelangen noch nicht genug Menschen in den Shop.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_1' => 'Platziere einen klaren Haupteinstieg zum Shop über den anderen Verkaufsoptionen.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_2' => 'Stimme die Nachricht in den Inhalten, auf WhatsApp und in den Verkaufsbereichen so ab, dass alles auf denselben nächsten Schritt hinweist.',
    'admin_leader_operating_system.leader.opportunity_action.app_signal_path.step_3' => 'Behalte die Blöcke bei, die Interesse wecken, aber trenne klar davon, wo der Klick zum Kauf oder zur Anmeldung unmittelbar erfolgen soll.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.label' => 'Mit kleineren Optimierungen in Bewegung bleiben',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.text' => 'Das Wachstumspotenzial ergibt sich nicht aus einem großen Problem, sondern aus mehreren kleineren Verbesserungsmöglichkeiten.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_1' => 'Leite weiterhin Besucher zu den stärksten Handlungsaufforderungen, die bereits gut funktionieren.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_2' => 'Teste weiterhin die Formulierung der Überschrift, die Reihenfolge der Handlungsaufforderungen und die Vertrauenselemente, um den Chancenwert stabil zu halten oder zu senken.',
    'admin_leader_operating_system.leader.opportunity_action.keep_momentum.step_3' => 'Prüfe weiterhin, ob zusätzliche Klicks zu Anmeldungen führen und nicht nur das Besucheraufkommen erhöhen.',
